+import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest'
+import { signPayload, notifyWebhook } from '../webhookNotifier.js'
+
+describe('signPayload', () => {
+  it('produces expected sha256 header', () => {
+    const secret = 'abcdef'
+    const body = JSON.stringify({ hello: 'world' })
+    const sig = signPayload(secret, body)
+    expect(sig).toMatch(/^sha256=[0-9a-f]{64}$/)
+  })
+})
+
+describe('notifyWebhook retry/backoff', () => {
+  beforeEach(() => {
+    vi.useFakeTimers()
+    // @ts-ignore
+    global.fetch = vi.fn()
+  })
+  afterEach(() => {
+    vi.useRealTimers()
+    // @ts-ignore
+    delete global.fetch
+    vi.resetAllMocks()
+  })
+
+  it('retries on network error and succeeds', async () => {
+    const fetchMock = global.fetch as unknown as vi.Mock
+    // first call: network error
+    fetchMock.mockRejectedValueOnce(new Error('network'))
+    // second call: 500 status
+    fetchMock.mockResolvedValueOnce({ ok: false, status: 500 })
+    // third call: success
+    fetchMock.mockResolvedValueOnce({ ok: true, status: 200 })
+
+    const config = { url: 'https://example.com/hook', secret: 's' }
+    const payload = { event: 'task.completed' }
+    const p = notifyWebhook(config, payload)
+
+    // advance timers for first backoff (1s)
+    await vi.runAllTimersAsync()
+    await p
+
+    expect(fetchMock).toHaveBeenCalledTimes(3)
+  })
+
+  it('gives up after max attempts', async () => {
+    const fetchMock = global.fetch as unknown as vi.Mock
+    fetchMock.mockRejectedValue(new Error('network'))
+
+    const config = { url: 'https://example.com/hook', secret: 's' }
+    const payload = { event: 'task.failed' }
+    const p = notifyWebhook(config, payload)
+
+    // advance timers to let retries run (1s + 2s + 4s)
+    await vi.runAllTimersAsync()
+    await p
+
+    expect(fetchMock).toHaveBeenCalledTimes(3)
+  })
+})
