@@ -0,0 +1,48 @@
+import crypto from 'crypto';
+import logger from '../logger.js';
+
+export type WebhookConfig = { url: string; secret: string };
+
+export function signPayload(secret: string, body: string): string {
+  const h = crypto.createHmac('sha256', Buffer.from(secret, 'utf8')).update(body, 'utf8').digest('hex');
+  return `sha256=${h}`;
+}
+
+export async function notifyWebhook(config: WebhookConfig, payload: Record<string, unknown>): Promise<void> {
+  const body = JSON.stringify(payload);
+  const signature = signPayload(config.secret, body);
+  const headers: Record<string, string> = {
+    'Content-Type': 'application/json',
+    'X-Pullwright-Signature': signature,
+    'X-Pullwright-Event': typeof payload.event === 'string' ? payload.event : 'task.completed',
+  };
+
+  const maxAttempts = 3;
+  let attempt = 0;
+  let delayMs = 1000;
+
+  while (attempt < maxAttempts) {
+    attempt++;
+    try {
+      // eslint-disable-next-line no-undef
+      const res = await fetch(config.url, { method: 'POST', headers, body, credentials: 'omit' as RequestCredentials });
+      if (res.ok) return;
+      if (res.status >= 500 && res.status < 600) {
+        logger.warn(`Webhook POST to ${config.url} failed with ${res.status} (attempt ${attempt})`);
+        if (attempt < maxAttempts) await new Promise((r) => setTimeout(r, delayMs));
+        delayMs *= 2;
+        continue;
+      }
+      // 4xx - do not retry
+      logger.warn(`Webhook POST to ${config.url} failed with ${res.status} (not retried)`);
+      return;
+    } catch (err) {
+      logger.warn(`Webhook POST to ${config.url} network error (attempt ${attempt}): ${err}`);
+      if (attempt < maxAttempts) await new Promise((r) => setTimeout(r, delayMs));
+      delayMs *= 2;
+      continue;
+    }
+  }
+
+  logger.error(`Webhook POST to ${config.url} failed after ${maxAttempts} attempts`);
+}
