+import { useState, useEffect } from 'react'
+import { getWebhook, saveWebhook, deleteWebhook } from '../../api/client'
+import SecretDisplay from './SecretDisplay'
+
+export default function WebhookCard() {
+  const [url, setUrl] = useState('')
+  const [stored, setStored] = useState<{ url: string | null; createdAt?: string } | null>(null)
+  const [secret, setSecret] = useState<string | null>(null)
+  const [_loading, setLoading] = useState(true)
+
+  useEffect(() => {
+    getWebhook().then((r) => { setStored(r); setUrl(r?.url ?? '') }).finally(() => setLoading(false))
+  }, [])
+
+  const onSave = async () => {
+    setLoading(true)
+    const res = await saveWebhook(url)
+    if (res) {
+      setStored({ url: res.url, createdAt: new Date().toISOString() })
+      setSecret(res.secret)
+    }
+    setLoading(false)
+  }
+
+  const onDelete = async () => {
+    setLoading(true)
+    await deleteWebhook()
+    setStored({ url: null })
+    setUrl('')
+    setSecret(null)
+    setLoading(false)
+  }
+
+  return (
+    <div className="bg-card rounded-xl border border-border p-5">
+      <h3 className="text-lg font-semibold mb-2">Webhook</h3>
+      <p className="text-sm text-muted-foreground mb-3">Receive signed task completion/failure notifications.</p>
+      <div className="flex gap-2">
+        <input value={url} onChange={(e) => setUrl(e.target.value)} className="flex-1 input" placeholder="https://hooks.example.com/your-hook" />
+        <button onClick={onSave} className="rounded-button px-3 py-1 bg-primary text-primary-foreground">Save</button>
+        {stored?.url ? <button onClick={onDelete} className="rounded-button px-3 py-1 bg-destructive text-primary-foreground">Remove</button> : null}
+      </div>
+      {secret ? <SecretDisplay secret={secret} /> : null}
+    </div>
+  )
+}
